8	/**
9	 * Calculates the size (width or height) of a given HTML element.
10	 *
11	 * This function performs an expensive calculation by temporarily changing the
12	 * display style of the element if it is not currently visible. It then uses
13	 * `getBoundingClientRect` to retrieve the size of the element.
14	 *
15	 * @param el - The HTML element whose size is to be calculated.
16	 * @param dimension - The dimension to measure ('width' or 'height').
17	 * @returns The size of the element in pixels. Returns 0 if the element is not provided.
18	 */
19	export function getSize(
20	  el: HTMLElement | undefined,
21	  dimension: 'width' | 'height'
22	): number {
23	  if (!el) return 0;
24	  const originalDisplay = el.style.display;
25	  if (!el.offsetParent && getComputedStyle(el).display === 'none') {
26	    el.style.display = 'inline-block';
27	  }
28	  const size = el.getBoundingClientRect()[dimension];
29	  el.style.display = originalDisplay;
30	  return size;
31	}
32	
33	/**
34	 * Options for updating the overflow handler.
35	 * Determines which items should be visible and which should be hidden
36	 * based on the container size, item sizes, and other constraints.
37	 */
38	export interface UpdateOverflowHandlerOptions {
39	  /** The container element that holds the items. */
40	  container: HTMLElement;
41	  /** An array of item elements to be managed for overflow. */
42	  items: HTMLElement[];
43	  /** An element that represents the offset, which can be shown or hidden based on overflow. Identified by `data-offset` attribute. */
44	  offset: HTMLElement | undefined;
45	  /** An array of sizes corresponding to each item in the `items` array. */
46	  sizes: number[];
47	  /** An array of sizes corresponding to each item in the fixed items array. */
48	  fixedSizes: number[];
49	  /** The size of the offset element. */
50	  offsetSize: number;
51	  /** The maximum number of items that can be visible at once. If undefined, all items can be visible. */
52	  maxVisibleItems?: number;
53	  /** The dimension to consider for overflow, either 'width' or 'height'. */
54	  dimension: 'width' | 'height';
55	  /** A callback function that is called when the visible or hidden items change. */
56	  onChange: (visibleItems: HTMLElement[], hiddenItems: HTMLElement[]) => void;
57	  /** An array of previously hidden items to compare against the new hidden items. */
58	  previousHiddenItems?: HTMLElement[];
59	}
60	
61	/**
62	 * Updates the overflow handler by determining which items should be visible and which should be hidden.
63	 *
64	 * @param options - Configuration options for updating the overflow handler.
65	 * @returns An array of hidden items after the update.
66	 */
67	export function updateOverflowHandler({
68	  container,
69	  items,
70	  offset,
71	  sizes,
72	  fixedSizes,
73	  offsetSize,
74	  maxVisibleItems,
75	  dimension,
76	  onChange,
77	  previousHiddenItems = [],
78	}: UpdateOverflowHandlerOptions): HTMLElement[] {
79	  const containerSize =
80	    dimension === 'width' ? container.clientWidth : container.clientHeight;
81	
82	  let visibleItems: HTMLElement[] = [];
83	  let hiddenItems: HTMLElement[] = [];
84	
85	  const totalSize = sizes.reduce((sum, size) => sum + size, 0);
86	  const totalFixedSize = fixedSizes.reduce((sum, size) => sum + size, 0);
87	
88	  if (totalSize + totalFixedSize <= containerSize) {
89	    visibleItems = maxVisibleItems
90	      ? items.slice(0, maxVisibleItems)
91	      : [...items];
92	    hiddenItems = maxVisibleItems ? items.slice(maxVisibleItems) : [];
93	  } else {
94	    const available = containerSize - offsetSize;
95	    let accumulated = 0;
96	
97	    for (let i = 0; i < items.length; i++) {
98	      const size = sizes[i];
99	      if (accumulated + size + totalFixedSize <= available) {
100	        visibleItems.push(items[i]);
101	        accumulated += size;
102	      } else {
103	        hiddenItems.push(items[i]);
104	      }
105	    }
106	  }
107	
108	  if (
109	    previousHiddenItems.length === hiddenItems.length &&
110	    previousHiddenItems.every((item, index) => item === hiddenItems[index])
111	  ) {
112	    return previousHiddenItems;
113	  }
114	
115	  visibleItems.forEach((item) => item.removeAttribute('data-hidden'));
116	  hiddenItems.forEach((item) => item.setAttribute('data-hidden', ''));
117	
118	  if (offset) {
119	    offset.toggleAttribute('data-hidden', hiddenItems.length !== 0);
120	  }
121	  onChange(visibleItems, hiddenItems);
122	  return hiddenItems;
123	}
124	
125	/**
126	 * Options for initializing an overflow handler.
127	 */
128	export interface OverflowHandlerOptions {
129	  /**
130	   * The container element that holds the items. along with offset item
131	   */
132	  container: HTMLElement;
133	  /**
134	   * Maximum number of visible items. If provided, only this number of items will be shown.
135	   */
136	  maxVisibleItems?: number;
137	  /**
138	   * Callback function invoked when the visible and hidden items change.
139	   * @param visibleItems - The array of items that are currently visible.
140	   * @param hiddenItems - The array of items that are currently hidden.
141	   */
142	  onChange: (visibleItems: HTMLElement[], hiddenItems: HTMLElement[]) => void;
143	  /**
144	   * The dimension to consider for overflow calculations. Defaults to 'width'.
145	   */
146	  dimension?: 'width' | 'height';
147	}
148	
149	/**
150	 * Represents an instance of an overflow handler.
151	 */
152	export interface OverflowHandler {
153	  /**
154	   * Disconnects the overflow handler, cleaning up any event listeners or resources.
155	   */
156	  disconnect: () => void;
157	}
158	
159	export function createOverflowHandler({
160	  container,
161	  maxVisibleItems,
162	  onChange,
163	  dimension = 'width',
164	}: OverflowHandlerOptions): OverflowHandler {
165	  // Error handling
166	  if (!(container instanceof HTMLElement)) {
167	    throw new Error('container must be an HTMLElement');
168	  }
169	  if (typeof onChange !== 'function') {
170	    throw new Error('onChange must be a function');
171	  }
172	  if (
173	    maxVisibleItems !== undefined &&
174	    (!Number.isInteger(maxVisibleItems) || maxVisibleItems <= 0)
175	  ) {
176	    throw new Error('maxVisibleItems must be a positive integer');
177	  }
178	
179	  const children = Array.from(container.children).filter(
180	    (item): item is HTMLElement => item instanceof HTMLElement
181	  );
182	  const offset = children.find((item) => item.hasAttribute('data-offset'));
183	  const fixedItems = children.filter((item) => item.hasAttribute('data-fixed'));
184	  const items = children.filter(
185	    (item) => item !== offset && !fixedItems.includes(item)
186	  );
187	
188	  const fixedSizes = fixedItems.map((item) => getSize(item, dimension));
189	  const sizes = items.map((item) => getSize(item, dimension));
190	  const offsetSize = getSize(offset, dimension);
191	
192	  let previousHiddenItems: HTMLElement[] = [];
193	
194	  function update() {
195	    previousHiddenItems = updateOverflowHandler({
196	      container,
197	      items,
198	      offset,
199	      sizes,
200	      fixedSizes,
201	      offsetSize,
202	      maxVisibleItems,
203	      dimension,
204	      onChange,
205	      previousHiddenItems,
206	    });
207	  }
208	
209	  const resizeObserver = new ResizeObserver(() =>
210	    requestAnimationFrame(update)
211	  );
212	  resizeObserver.observe(container);
213	
214	  requestAnimationFrame(update); // Initial update
215	
216	  return {
217	    disconnect() {
218	      resizeObserver.disconnect();
219	    },
220	  };
221	}
