11	  useEffect,
12	  useMemo,
13	  useRef,
14	  useState,
15	} from 'react';
16	import { useResizeObserver } from './useResizeObserver';
17	import { usePreviousValue } from './usePreviousValue';
18	
19	type Item = {
20	  id: string;
21	};
22	
23	/**
24	 * Manages overflow items in a container by automatically hiding items that don't fit.
25	 * @param items - Array of items to manage for overflow, each must have an `id` property.
26	 * @param containerRef - React ref to the container element that holds the items.
27	 * @param offsetRef - Optional ref to an offset element (like a "more" button) whose width is reserved when calculating available space.
28	 * @param maxItems - Optional maximum number of visible items. If undefined, only container space constrains visibility.
29	 * @param onChange - Optional callback called when hidden items change. Receives array of currently hidden items.
30	 * @returns Object with `visibleItems` (items to display), `hiddenItems` (items that don't fit), and `itemRefHandler` (function to attach refs to items for width measurement).
31	 */
32	const useOverflowItems = <T extends Item>(
33	  items: T[] | ReactNode,
34	  containerRef: RefObject<HTMLDivElement>,
35	  offsetRef?: RefObject<HTMLDivElement>,
36	  maxItems?: number,
37	  onChange?: (hiddenItems: T[]) => void
38	) => {
39	  const itemsRef = useRef<Map<string, number> | null>(null);
40	  const [maxWidth, setMaxWidth] = useState(0);
41	  const overflowItems = useMemo(
42	    () => (Array.isArray(items) ? items : []),
43	    [items]
44	  );
45	
46	  const handleResize = () => {
47	    if (containerRef.current) {
48	      const offset = offsetRef?.current?.offsetWidth || 0;
49	      const newMax = containerRef.current.offsetWidth - offset;
50	      setMaxWidth(newMax);
51	    }
52	  };
53	  useResizeObserver({
54	    ref: containerRef,
55	    onResize: handleResize,
56	  });
57	
58	  const getMap = () => {
59	    if (!itemsRef.current) {
60	      itemsRef.current = new Map();
61	    }
62	    return itemsRef.current;
63	  };
64	
65	  const itemRefHandler = (id: string, node: HTMLDivElement | null) => {
66	    const map = getMap();
67	    if (node) {
68	      const style = getComputedStyle?.(node);
69	      const totalWidth =
70	        node.offsetWidth +
71	        parseInt(style.marginLeft) +
72	        parseInt(style.marginRight);
73	      map.set(id, totalWidth);
74	    }
75	
76	    return () => {
77	      map.delete(id);
78	    };
79	  };
80	
81	  const getVisibleItems = () => {
82	    if (!containerRef) {
83	      return overflowItems;
84	    }
85	
86	    const map = getMap();
87	    let maxReached = false;
88	    let accumulatedWidth = 0;
89	
90	    const visibleItems = overflowItems
91	      .slice(0, maxItems)
92	      .reduce((prev, cur) => {
93	        if (maxReached) {
94	          return prev;
95	        }
96	
97	        const itemWidth = map.get(cur.id) || 0;
98	        const willFit = accumulatedWidth + itemWidth <= maxWidth;
99	        if (willFit) {
100	          accumulatedWidth += itemWidth;
101	          prev.push(cur);
102	        } else {
103	          maxReached = true;
104	        }
105	        return prev;
106	      }, [] as T[]);
107	    return visibleItems;
108	  };
109	
110	  // Memoize visible items calculation to avoid recalculating on every render
111	  const visibleItems = useMemo(() => {
112	    return getVisibleItems();
113	    // eslint-disable-next-line  react-hooks/exhaustive-deps -- https://github.com/carbon-design-system/carbon/issues/20452
114	  }, [overflowItems, maxWidth, maxItems]);
115	
116	  // Memoize hidden items calculation
117	  const hiddenItems = useMemo(() => {
118	    return overflowItems.slice(visibleItems.length);
119	  }, [overflowItems, visibleItems]);
120	
121	  // Use previous value to compare and only call onChange when needed
122	  const previousHiddenItems = usePreviousValue(hiddenItems);
123	
124	  // Only call onChange if hidden items actually changed
125	  useEffect(() => {
126	    if (previousHiddenItems && onChange) {
127	      const hasChanged =
128	        hiddenItems.length !== previousHiddenItems.length ||
129	        hiddenItems.some((item, index) => item !== previousHiddenItems[index]);
130	
131	      if (hasChanged) {
132	        onChange(hiddenItems);
133	      }
134	    }
135	  }, [hiddenItems, previousHiddenItems, onChange]);
136	
137	  return {
138	    visibleItems,
139	    itemRefHandler,
140	    hiddenItems,
141	  };
142	};
143	
144	export default useOverflowItems;
